curl -s -X POST "https://slack.com/api/conversations.list" -H "Content-Type: application/json" -d '{"token": "<TOKEN>", "types": "public_channel", "limit": 100}' | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        if 'launch' in ch['name'].lower() or 'planning' in ch['name'].lower():
            print(json.dumps(ch, indent=2))
else:
    print(json.dumps(data, indent=2))
"

curl -s -X POST "https://slack.com/api/conversations.history" -H "Content-Type: application/json" -d '{"token": "<TOKEN>", "channel": "C_LAUNCH", "limit": 100}' | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for msg in data['messages']:
        if msg.get('user') and ('tada' in str(msg.get('reactions', [])) or 'launch' in msg.get('text','').lower() or 'date' in msg.get('text','').lower()):
            print(json.dumps(msg, indent=2))
            print('---')
    # Also print all messages to be thorough
    print('=== ALL MESSAGES ===')
    for msg in data['messages']:
        print(json.dumps({'user': msg.get('user'), 'text': msg.get('text',''), 'ts': msg.get('ts',''), 'reactions': msg.get('reactions',[])}))
else:
    print(json.dumps(data, indent=2))
"

